#!/usr/bin/env python3
"""Fetch order pages and customer records from the local order service.

Usage:
    fetch.py pages
    fetch.py customers <file with one customer id per line>

Handles token refresh (401), rate limiting (429 + Retry-After), transient
5xx / network errors and malformed 200 bodies by retrying.  Every non-200
response is logged in full to data/http_log.jsonl.  Anything not recognised
raises Fatal so it can be inspected instead of guessed at.
"""
import email.utils
import http.client
import json
import os
import re
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
DATA = "/tmp/recon/data"
PAGES_DIR = os.path.join(DATA, "pages")
CUST_DIR = os.path.join(DATA, "customers")
LOG_PATH = os.path.join(DATA, "http_log.jsonl")
PAUSE = 0.05          # polite gap between requests
MAX_ATTEMPTS = 200


class Fatal(Exception):
    pass


def header(headers, name):
    for k, v in headers.items():
        if k.lower() == name.lower():
            return v
    return None


class Client:
    def __init__(self):
        os.makedirs(DATA, exist_ok=True)
        self.token = None
        self.counts = {}
        self.tokens = []
        self.log = open(LOG_PATH, "a")
        self.total_wait = 0.0

    def bump(self, key):
        self.counts[key] = self.counts.get(key, 0) + 1

    def note(self, **kw):
        kw["ts"] = round(time.time(), 3)
        self.log.write(json.dumps(kw) + "\n")
        self.log.flush()

    def raw(self, method, path, auth):
        headers = {"Accept": "application/json"}
        if auth:
            headers["Authorization"] = "Bearer " + self.token
        data = b"" if method == "POST" else None
        req = urllib.request.Request(BASE + path, data=data, method=method,
                                     headers=headers)
        time.sleep(PAUSE)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, dict(resp.headers.items()), resp.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers.items()), e.read()

    def retry_after(self, headers, body):
        """Seconds to wait, from the Retry-After header and/or JSON body."""
        waits = []
        h = header(headers, "Retry-After")
        if h is not None:
            h = h.strip()
            try:
                waits.append(float(h))
            except ValueError:
                dt = email.utils.parsedate_to_datetime(h)
                waits.append(max(0.0, dt.timestamp() - time.time()))
        try:
            b = json.loads(body)
            if isinstance(b, dict) and isinstance(b.get("retry_after"), (int, float)):
                waits.append(float(b["retry_after"]))
        except ValueError:
            pass
        if not waits:
            return None
        if len(set(waits)) > 1:
            self.note(warning="retry_after disagreement", waits=waits)
        return max(waits)

    def refresh_token(self):
        status, data = self.call("POST", "/token", auth=False,
                                 validate=lambda d: None if isinstance(d, dict) and isinstance(d.get("token"), str) and d["token"] else "no token in body")
        self.token = data["token"]
        self.tokens.append(self.token)
        self.bump("token_issued")

    def call(self, method, path, auth=True, ok_statuses=(), validate=None):
        for attempt in range(1, MAX_ATTEMPTS + 1):
            if auth and self.token is None:
                self.refresh_token()
            try:
                status, headers, body = self.raw(method, path, auth)
            except (urllib.error.URLError, http.client.HTTPException, OSError) as e:
                self.bump("network_error")
                self.note(path=path, attempt=attempt, error=repr(e))
                time.sleep(min(0.25 * attempt, 5))
                continue

            text = body.decode("utf-8", "replace")
            if status == 200:
                try:
                    data = json.loads(body)
                except ValueError:
                    self.bump("bad_json_200")
                    self.note(path=path, attempt=attempt, status=status,
                              headers=headers, body=text[:3000], error="bad json")
                    time.sleep(0.25)
                    continue
                problem = validate(data) if validate else None
                if problem:
                    self.bump("invalid_200")
                    self.note(path=path, attempt=attempt, status=status,
                              headers=headers, body=text[:3000], error=problem)
                    if self.counts["invalid_200"] > 50:
                        raise Fatal("too many invalid 200 bodies; last: %s" % problem)
                    time.sleep(0.25)
                    continue
                self.bump("ok_200")
                return status, data

            self.bump("http_%d" % status)
            self.note(path=path, attempt=attempt, status=status,
                      headers=headers, body=text[:3000],
                      token=self.token if auth else None)
            if status == 401 and auth:
                self.token = None
                continue
            if status == 429:
                wait = self.retry_after(headers, body)
                if wait is None:
                    raise Fatal("429 with no wait time: %s %s" % (headers, text))
                self.total_wait += wait
                time.sleep(wait + 0.05)
                continue
            if status in ok_statuses:
                return status, text
            if 500 <= status < 600:
                time.sleep(min(0.25 * attempt, 5))
                continue
            raise Fatal("unexpected status %d for %s: %s" % (status, path, text[:500]))
        raise Fatal("gave up on %s after %d attempts" % (path, MAX_ATTEMPTS))


ORDER_PATH = re.compile(r"^/orders\?page=(\d+)$")


def validate_page(expected):
    def check(d):
        if not isinstance(d, dict):
            return "body not an object"
        for k in ("page", "total_pages", "items", "next"):
            if k not in d:
                return "missing key %s" % k
        if d["page"] != expected:
            return "page %r != requested %r" % (d["page"], expected)
        if not isinstance(d["items"], list):
            return "items not a list"
        if not isinstance(d["total_pages"], int):
            return "total_pages not int"
        if d["next"] is not None and not isinstance(d["next"], str):
            return "next not str/null"
        if any(not isinstance(it, dict) or "id" not in it for it in d["items"]):
            return "item without id"
        return None
    return check


def fetch_pages(client):
    os.makedirs(PAGES_DIR, exist_ok=True)
    meta = []
    path = "/orders?page=1"
    visited = set()
    while path is not None:
        m = ORDER_PATH.match(path)
        if not m:
            raise Fatal("unexpected next path %r" % path)
        n = int(m.group(1))
        if n in visited:
            raise Fatal("next loops back to page %d" % n)
        visited.add(n)
        _, data = client.call("GET", path, validate=validate_page(n))
        with open(os.path.join(PAGES_DIR, "page_%03d.json" % n), "w") as f:
            json.dump(data, f)
        meta.append({"page": n, "total_pages": data["total_pages"],
                     "n_items": len(data["items"]), "next": data["next"]})
        print("page %d/%d items=%d next=%s" % (n, data["total_pages"],
              len(data["items"]), data["next"]), flush=True)
        path = data["next"]

    # Make sure every page 1..total_pages was fetched, whatever "next" said.
    totals = {m["total_pages"] for m in meta}
    for n in range(1, max(totals) + 1):
        if n not in visited:
            print("page %d not reached via next; fetching directly" % n, flush=True)
            _, data = client.call("GET", "/orders?page=%d" % n, validate=validate_page(n))
            with open(os.path.join(PAGES_DIR, "page_%03d.json" % n), "w") as f:
                json.dump(data, f)
            meta.append({"page": n, "total_pages": data["total_pages"],
                         "n_items": len(data["items"]), "next": data["next"],
                         "direct": True})
    with open(os.path.join(DATA, "pages_meta.json"), "w") as f:
        json.dump(meta, f, indent=1)


def validate_customer(cid):
    def check(d):
        if not isinstance(d, dict):
            return "body not an object"
        if d.get("id") != cid:
            return "id %r != requested %r" % (d.get("id"), cid)
        for k in ("region", "discount_pct"):
            if k not in d:
                return "missing key %s" % k
        return None
    return check


def fetch_customers(client, ids):
    os.makedirs(CUST_DIR, exist_ok=True)
    summary = {}
    for cid in ids:
        if not re.fullmatch(r"[A-Za-z0-9_-]+", cid):
            raise Fatal("refusing odd customer id %r" % cid)
        status, data = client.call("GET", "/customers/" + cid, ok_statuses=(404,),
                                   validate=validate_customer(cid))
        if status == 404:
            # Confirm a 404 is stable before believing it.
            confirmations = []
            for _ in range(3):
                time.sleep(0.5)
                s2, d2 = client.call("GET", "/customers/" + cid, ok_statuses=(404,),
                                     validate=validate_customer(cid))
                confirmations.append(s2)
                if s2 == 200:
                    status, data = s2, d2
                    break
            summary[cid] = {"status": status, "confirmations": confirmations}
            if status == 404:
                print("customer %s: 404 (confirmed x%d)" % (cid, len(confirmations)), flush=True)
                continue
        with open(os.path.join(CUST_DIR, cid + ".json"), "w") as f:
            json.dump(data, f)
        summary.setdefault(cid, {"status": 200})
        print("customer %s: %s" % (cid, json.dumps(data)), flush=True)
    with open(os.path.join(DATA, "customers_meta.json"), "w") as f:
        json.dump(summary, f, indent=1)


def main():
    client = Client()
    t0 = time.time()
    try:
        if sys.argv[1] == "pages":
            fetch_pages(client)
        elif sys.argv[1] == "customers":
            with open(sys.argv[2]) as f:
                ids = [line.strip() for line in f if line.strip()]
            fetch_customers(client, ids)
        else:
            raise SystemExit("unknown command")
    finally:
        print("elapsed %.1fs, counts=%s, tokens=%s, total 429 wait=%.1fs"
              % (time.time() - t0, client.counts, client.tokens, client.total_wait),
              flush=True)


if __name__ == "__main__":
    main()

